checks=[]; failures=[]
def check(name,ok,detail=''):
  row={'check':name,'status':'PASS' if ok else 'FAIL','detail':detail}; checks.append(row)
  if not ok: failures.append(row)
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
texts={}
for rel,h in POST_HASHES.items():
  p=repo/rel
  check('exists: '+rel,p.is_file())
  if not p.is_file(): continue
  got=sha(p); check('post hash: '+rel,got==h,f'expected={h} got={got}')
  txt=p.read_text(encoding='utf-8'); texts[rel]=txt
  bad=[str(i) for i,l in enumerate(txt.splitlines(),1) if l.rstrip(' \t')!=l]
  check('no trailing whitespace: '+rel,not bad,','.join(bad[:10]))

# Every exact R2 replacement is locked in both directions.
for i,e in enumerate(EDITS,1):
  rel=e['path']; txt=texts.get(rel,'')
  check(f'edit {i:03d} old absent: {rel}',e['old'] not in txt,e['old'][:120])
  check(f'edit {i:03d} new present: {rel}',e['new'] in txt,e['new'][:120])

combined='\n'.join(texts.values())
for label,pat in TARGETED_PATTERNS.items():
  check('targeted internal residue absent: '+label,re.search(pat,combined,re.I) is None)

# Explicit public-language keep guards: do not over-clean valid neutral/safety/legal concepts.
keep_guards=[
 ('buyer methodology remains neutral','rangere merker' in texts.get('src/content/decision-guides/ear-vs-neck-vns.ts','')),
 ('medical boundary wording retained','diagnos' in combined.lower() and 'treat' in combined.lower()),
 ('VNS evidence boundary retained','evidence' in combined.lower()),
]
for name,ok in keep_guards: check(name,ok)

with (out/'search-dominance-1e2c-r2-checks.csv').open('w',encoding='utf-8',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['check','status','detail']); w.writeheader(); w.writerows(checks)
result={
 'schema':'neuvago-search-dominance-1e2c-r2-public-editorial-residue-cleanup-audit-v1',
 'status':'PASS' if not failures else 'FAIL',
 'checks_total':len(checks),'checks_passed':sum(x['status']=='PASS' for x in checks),'failures':failures,
 'modified_source_files':len(POST_HASHES),'exact_editorial_replacements':len(EDITS),
 'targeted_residue_patterns':len(TARGETED_PATTERNS),
 'scope_note':'Public editorial cleanup only; URLs, canonicals, evidence lanes, claims and regulatory facts are not intentionally changed.'
}
(out/'SEARCH-DOMINANCE-1E2C-R2-AUDIT.json').write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print(json.dumps(result,indent=2,ensure_ascii=False)); sys.exit(1 if failures else 0)
